from jsonb_to_recordset($json$[{"id":"che-pe-233","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Transition metals are noted for showing","options":["only the oxidation state +1","variable oxidation states","no cations at all","a unique oxidation state of −4"],"answer_index":1,"explanation":"Both ns and (n−1)d electrons can take part in bonding, so several OS are common.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-234","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In most of its compounds oxygen exhibits the oxidation state","options":["+2","−2","+6","0 only"],"answer_index":1,"explanation":"Oxygen is highly electronegative and usually completes its octet by gaining or sharing two electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-235","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Nitrogen can show oxidation states ranging from −3 in ammonia to +5 in","options":["nitrogen gas","nitric acid","hydrazine","the nitride ion"],"answer_index":1,"explanation":"HNO₃ and nitrates use all five valence electrons of N; NH₃ uses the −3 state.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-236","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Manganese attains its highest oxidation state of +7 in the","options":["manganous ion Mn²⁺","permanganate ion","manganese metal","MnO solid only"],"answer_index":1,"explanation":"In MnO₄⁻ the seven 4s and 3d electrons of Mn are all involved in bonding.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-237","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Sulphur can show the +6 state in SO₃, whereas oxygen rarely exceeds −2, because sulphur has","options":["a smaller size than oxygen","vacant 3d orbitals","fewer valence electrons","no p orbitals"],"answer_index":1,"explanation":"The 3d orbitals of S allow expansion of the octet; second-period O cannot do this.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-238","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Chlorine exhibits odd positive oxidation states +1, +3, +5 and +7 in addition to","options":["+8","−1","−7","+2 only"],"answer_index":1,"explanation":"The −1 state is the halide; the odd positive states appear in oxoacids and oxides as 3s and 3p (and 3d) electrons are unpaired.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-239","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Group-14 elements typically form tetravalent compounds, matching","options":["two valence electrons","four valence electrons","six valence electrons","a noble-gas vacancy of one"],"answer_index":1,"explanation":"The valence configuration ns² np² supplies four electrons for four bonds (CCl₄, SiCl₄, …).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-240","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the 3d metals, the highest oxidation state is +7, shown by manganese, equal to the total of its","options":["3p electrons only","4s and 3d electrons","4p electrons","neutrons in ⁵⁵Mn"],"answer_index":1,"explanation":"Mn is 4s² 3d⁵; using all seven electrons gives Mn(VII) as in KMnO₄. Iron does not reach +8 in ordinary compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-241","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic character of elements increases on moving","options":["across a period from left to right","down a group","from Cs to Li","from Na to Cl"],"answer_index":1,"explanation":"Size grows and IE falls down a group, so the atom loses electrons more readily.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-242","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic character of elements decreases on moving from left to right across a","options":["group","period","set of isotopes","noble-gas family"],"answer_index":1,"explanation":"IE and electronegativity rise across a period, so electron loss becomes less favourable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-243","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metals tend to lose valence electrons and form","options":["anions","cations","noble-gas atoms of lower Z","free neutrons"],"answer_index":1,"explanation":"Electropositive behaviour is the chemical signature of metallic character.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-244","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Non-metals tend to gain electrons and form anions or","options":["metallic lattices","covalent molecules","only monatomic cations","bare nuclei"],"answer_index":1,"explanation":"High IE and high electronegativity favour electron gain or sharing rather than cation formation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
